function Cactus({ side }: { side: number }) {
  return (
    <group position={[side * 0.72, C.platformH / 2, 0.05]}>
      <Part geometry={POT} color={COLORS.pot} position={[0, 0.13, 0]} outlineWidth={0.045} />
